	public static FrameworkElement Create(string name, double size, Brush fill, bool filled)
	{
		Canvas canvas = new Canvas();
		canvas.Width = size;
		canvas.Height = size;
		canvas.SnapsToDevicePixels = true;
		canvas.UseLayoutRounding = true;
		canvas.IsHitTestVisible = false;
		Canvas canvas2 = canvas;
		Geometry geometry = GetGeometry(name, filled);
		if (geometry == null)
		{
			return canvas2;
		}
		Path path = new Path();
		path.Data = geometry;
		path.Fill = fill;
		Path path2 = path;
		double num = size / 20.0;
		if (Math.Abs(num - 1.0) > 0.0001)
		{
			ScaleTransform scaleTransform = new ScaleTransform(num, num);
			scaleTransform.Freeze();
			path2.RenderTransform = scaleTransform;
		}
		canvas2.Children.Add(path2);
		return canvas2;
	}

	public static bool Has(string name)
	{
		if (name != null)
		{
			return Paths.ContainsKey(name);
		}
		return false;
	}

	public static Geometry GetGeometry(string name, bool filled)
	{
		if (name == null)
		{
			return null;
		}
		string key = (filled ? (name + "|f") : (name + "|r"));
		lock (_cache)
		{
			if (_cache.TryGetValue(key, out var value))
			{
				return value;
			}
			if (!Paths.TryGetValue(name, out var value2))
			{
				return null;
			}
			value = Geometry.Parse("F1 " + value2[filled ? 1 : 0]);
			value.Freeze();
			_cache[key] = value;
			return value;
		}
	}

	public static string BatteryName(int percent, bool charging)
	{
		if (charging)
		{
			return "battery_charge";
		}
		int num = (int)Math.Round((double)Math.Max(0, Math.Min(100, percent)) / 10.0);
		return "battery_" + num;
	}
